import{_ as t,o,c as a,a5 as i}from"./chunks/framework.BfQ7H7Qx.js";const g=JSON.parse('{"title":"Plan — FR 3.2.9: Delete Account","description":"","frontmatter":{},"headers":[],"relativePath":"feature/srs/01-authentication/3-2-9-delete-account/plan.md","filePath":"feature/srs/01-authentication/3-2-9-delete-account/plan.md"}'),c={name:"feature/srs/01-authentication/3-2-9-delete-account/plan.md"};function n(r,e,d,s,l,h){return o(),a("div",null,[...e[0]||(e[0]=[i('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Domain Index</a> · <a href="./spec.html">Spec</a> · <strong>Plan</strong> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="plan-—-fr-3-2-9-delete-account" tabindex="-1">Plan — FR 3.2.9: Delete Account <a class="header-anchor" href="#plan-—-fr-3-2-9-delete-account" aria-label="Permalink to &quot;Plan — FR 3.2.9: Delete Account&quot;">​</a></h1><p>&gt; <a href="./spec.html">spec.md</a> — Soft-delete account, 2 flow xác thực (password / OTP), chặn nếu là Owner duy nhất Agency active.</p><h2 id="quyet-đinh-cau-hoi-mo-spec-edge-cases" tabindex="-1">Quyết định câu hỏi mở (spec Edge Cases) <a class="header-anchor" href="#quyet-đinh-cau-hoi-mo-spec-edge-cases" aria-label="Permalink to &quot;Quyết định câu hỏi mở (spec Edge Cases)&quot;">​</a></h2><p>Spec để mở: &quot;User là Owner Agency active → deactivate thì Agency xử lý sao?&quot; — <strong>Chốt với Trung: Chặn, bắt transfer trước.</strong> Áp dụng chung cho cả 2 flow.</p><p>Spec để mở: &quot;User OAuth-only (không có password) muốn deactivate thì sao, vì không thể verify password?&quot; — <strong>Chốt: thêm flow OTP qua email (2026-09-23).</strong></p><h2 id="ky-thuat" tabindex="-1">Kỹ thuật <a class="header-anchor" href="#ky-thuat" aria-label="Permalink to &quot;Kỹ thuật&quot;">​</a></h2><ul><li><code>DeactivateRequest(password, otpCode)</code> — cả 2 field optional, không validation annotation.</li><li><code>POST /api/v1/auth/deactivate/send-otp</code> (Bearer, không body) — sinh OTP 6 số, lưu Redis <code>otp:deactivate:{userId}</code> TTL 10 phút, gửi email qua <code>mailService.sendOtpEmail</code>.</li><li><code>POST /api/v1/auth/deactivate { password?, otpCode? }</code> (Bearer + <code>refreshToken</code> cookie): <ul><li><code>user.passwordHash != null</code> → verify <code>password</code> (bcrypt) → sai → 400 <code>WRONG_CURRENT_PASSWORD</code>.</li><li><code>user.passwordHash == null</code> → verify <code>otpCode</code> với Redis key → sai/thiếu/hết hạn → 400 <code>OTP_INVALID</code> → đúng thì xóa key.</li></ul></li><li><code>agencyRepository.findByOwnerId(userId)</code> → có Agency <code>EntityStatus.ACTIVE</code>? → 409 <code>AGENCY_OWNERSHIP_ACTIVE</code>.</li><li>Không có → <code>setStatus(UserStatus.DEACTIVATED)</code> (soft delete), KHÔNG xóa cứng.</li><li><strong>MỚI</strong>: Sau khi save status, blacklist accessToken + refreshToken (nếu có) qua <code>jwtUtil.blacklistToken()</code> — best-effort, bắt <code>JwtException</code> bỏ qua nếu token thiếu/hỏng. Cắt session ngay lập tức, không đợi refresh lần sau.</li><li>Sau deactivate, login/refresh → <code>checkStatus</code> → 403 <code>ACCOUNT_DEACTIVATED</code> (backup, đã có blacklist nên không còn là cơ chế cắt session duy nhất).</li></ul><h2 id="luong" tabindex="-1">Luồng <a class="header-anchor" href="#luong" aria-label="Permalink to &quot;Luồng&quot;">​</a></h2><p><strong>Flow A (có password):</strong></p><ol><li>Auth → userId.</li><li>Verify password → sai → 400.</li><li>Check Agency active (owner) → có → 409.</li><li><code>status=DEACTIVATED</code> → blacklist accessToken + refreshToken → 200.</li></ol><p><strong>Flow B (OAuth-only):</strong></p><ol><li>Auth → userId → gọi <code>send-otp</code> → sinh OTP, lưu Redis, gửi email → 200.</li><li>Client gọi <code>deactivate { otpCode }</code> → auth → userId.</li><li>Verify OTP với Redis → sai/thiếu/hết hạn → 400 → đúng thì xóa key.</li><li>Check Agency active (owner) → có → 409.</li><li><code>status=DEACTIVATED</code> → blacklist accessToken + refreshToken → 200.</li></ol><h2 id="data-model" tabindex="-1">Data Model <a class="header-anchor" href="#data-model" aria-label="Permalink to &quot;Data Model&quot;">​</a></h2><ul><li><code>users.status</code> → <code>DEACTIVATED</code> (enum value).</li><li><code>users.password_hash</code> — dùng để phân nhánh flow (null → OTP, not null → password).</li><li><code>agencies.owner_id</code>, <code>agencies.status</code>.</li><li>Redis key <code>otp:deactivate:{userId}</code> — TTL 10 phút, giá trị OTP 6 số.</li></ul><h2 id="rui-ro" tabindex="-1">Rủi ro <a class="header-anchor" href="#rui-ro" aria-label="Permalink to &quot;Rủi ro&quot;">​</a></h2><ul><li>Không xóa cứng (giữ Agency/Workspace membership). User muốn khôi phục → nhờ Admin (ngoài scope).</li><li>Flow B: nếu mailService lỗi (send-otp thất bại), user OAuth-only không có cách nào khác để deactivate — cần theo dõi log lỗi gửi mail.</li><li>UI/UX 2 bước (send-otp rồi mới nhập OTP) cho user OAuth-only — <strong>cần FE xác nhận thiết kế</strong> (xem spec.md mục 4).</li></ul><h2 id="tich-hop-frontend-web-mobile-đa-trien-khai" tabindex="-1">Tích hợp Frontend Web &amp; Mobile (Đã triển khai) <a class="header-anchor" href="#tich-hop-frontend-web-mobile-đa-trien-khai" aria-label="Permalink to &quot;Tích hợp Frontend Web &amp; Mobile (Đã triển khai)&quot;">​</a></h2><ul><li><strong>Web (<code>brandhub-web</code>):</strong> <code>src/pages/profile/index.tsx</code>, <code>src/services/authService.ts</code> — đồng bộ song song locale <code>vi</code>/<code>en</code> (<code>profile.deactivate.*</code>) và semantic Light/Dark mode tokens.</li><li><strong>Mobile (<code>brandhub-mobile-app</code>):</strong> <code>src/screens/settings/AccountSettingsScreen.tsx</code>, <code>src/services/authService.ts</code> — đồng bộ API contract, token state và kiểm tra lỗi nhất quán với Web.</li><li><strong>Tài liệu tham chiếu:</strong> <a href="./../../../../ba/02-authentication-profile.html">BA Authentication &amp; Profile</a> · <a href="./../../../modules/README.html">Module Specs Index</a> · <a href="./test.html">Test Suite</a>.</li></ul><h2 id="endpoint-authorization-error-mapping-matrix" tabindex="-1">Endpoint, Authorization &amp; Error Mapping Matrix <a class="header-anchor" href="#endpoint-authorization-error-mapping-matrix" aria-label="Permalink to &quot;Endpoint, Authorization &amp; Error Mapping Matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Aspect</th><th style="text-align:left;">Specification</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>FR / Feature</strong></td><td style="text-align:left;"><code>FR 3.2.9</code> — Delete Account</td></tr><tr><td style="text-align:left;"><strong>HTTP / WS Endpoints</strong></td><td style="text-align:left;"><code>POST /api/v1/auth/deactivate · POST /api/v1/auth/deactivate/send-otp</code></td></tr><tr><td style="text-align:left;"><strong>Authorized Canonical Roles</strong></td><td style="text-align:left;"><code>Owner, Manager, Creator, Client, Admin</code></td></tr><tr><td style="text-align:left;"><strong>Controller -&gt; Service</strong></td><td style="text-align:left;"><code>AuthController</code> -&gt; <code>AuthServiceImpl, JwtUtil, MailService</code></td></tr><tr><td style="text-align:left;"><strong>Persistence / Cache Targets</strong></td><td style="text-align:left;">PostgreSQL <code>users</code> (<code>status = DEACTIVATED</code>), <code>agencies</code>; Redis <code>otp:deactivate:{userId}</code>, <code>jwt:blacklist:{jti}</code></td></tr><tr><td style="text-align:left;"><strong>Business Rule Invariants</strong></td><td style="text-align:left;"><code>BR-10, BR-16</code></td></tr><tr><td style="text-align:left;"><strong>Error Code Contract</strong></td><td style="text-align:left;"><code>400 WRONG_CURRENT_PASSWORD</code> / <code>OTP_INVALID</code>, <code>401 UNAUTHORIZED</code>, <code>409 AGENCY_OWNERSHIP_ACTIVE</code></td></tr></tbody></table><h2 id="frontend-cache-i18n-theme-architecture" tabindex="-1">Frontend Cache, i18n &amp; Theme Architecture <a class="header-anchor" href="#frontend-cache-i18n-theme-architecture" aria-label="Permalink to &quot;Frontend Cache, i18n &amp; Theme Architecture&quot;">​</a></h2><ul><li><strong>Web State &amp; Query Management (<code>brandhub-web</code>):</strong><ul><li>Components &amp; Hooks: <code>src/pages/profile/index.tsx</code>, <code>src/services/authService.ts</code>.</li><li>Query Keys &amp; Cache Invalidation: Scoped by authenticated <code>userId</code>, <code>agencyId</code>, or <code>workspaceId</code> so switching tenants or logging out never leaks cached records across boundaries.</li><li>Conflict &amp; Error Recovery: Preserves in-progress user form state on <code>400</code>/<code>409</code> responses, disables duplicate in-flight submissions, and never falls back to hardcoded mock data.</li></ul></li><li><strong>Mobile Parity (<code>brandhub-mobile-app</code>):</strong><ul><li>Screens &amp; Services: <code>src/screens/settings/AccountSettingsScreen.tsx</code>, <code>src/services/authService.ts</code>.</li><li>Uses shared REST/WS contract, <code>expo-secure-store</code> Bearer token injection, and mobile <code>workspaceStore</code> / <code>authStore</code> synchronization.</li></ul></li><li><strong>Localization &amp; Theme Standards:</strong><ul><li>Key-parallel Vietnamese (<code>vi</code>) and English (<code>en</code>) locale entries under <code>profile.deactivate.*</code> with zero hardcoded strings.</li><li>Semantic CSS variables / Tailwind <code>dark:</code> variants on Web and <code>useTheme()</code> semantic tokens on Mobile verified across Light and Dark modes.</li></ul></li><li><strong>Observability &amp; Audit Correlation:</strong><ul><li>Propagates <code>X-Request-Id</code> from <code>brandhub-api-gateway</code> into <code>ApiResponse.requestId</code> and structured backend logs / <code>audit_logs</code> where security-sensitive mutations occur.</li></ul></li><li><strong>BA &amp; Module Traceability:</strong> <a href="./../../../../ba/02-authentication-profile.html">BA Domain Spec</a> · <a href="./../../../../ba/README.html">BA Overview</a> · <a href="./../../../modules/README.html">Module Specs Index</a>.</li></ul>',23)])])}const p=t(c,[["render",n]]);export{g as __pageData,p as default};
